4	/**
5	 * Reads a scenario as JSON on stdin and writes its results as JSON on stdout.
6	 *
7	 * The calculation module knows nothing about processes: it THROWS on invalid
8	 * input, and translating that into stderr plus a non-zero exit is this file's
9	 * only other job. Stdout therefore carries the results document or nothing.
10	 */
11	const main = (): void => {
12	  // fd 0 read to EOF — the scenario is a single JSON document, so this avoids
13	  // stream plumbing and the races that come with it.
14	  const input = readFileSync(0, "utf8");
15	
16	  try {
17	    const scenario = JSON.parse(input) as Scenario;
18	    process.stdout.write(JSON.stringify(runScenario(scenario)));
19	  } catch (error) {
20	    process.stderr.write(
21	      `${error instanceof Error ? error.message : String(error)}\n`,
22	    );
23	    process.exit(1);
24	  }
25	};
26	
27	main();
28

