293	  // because 10 % is linear, a per-item reading yields the same 225 G, so it
294	  // does NOT discriminate policy-base from per-item-base either.
295	  // The surcharge is unconditional (every item in a quote counts as a first
296	  // insurance, regardless of customer history), so there is no negative
297	  // partner to bracket it with. 200 base + 20 + 5 fee = 225 G.
298	  it("should add 10 % initial assessment surcharge for a first insurance", () => {
299	    const output = runScenario({
300	      customer: { yearsWithMHPCO: 0 },
301	      steps: [
302	        {
303	          op: "quote",
304	          items: [
305	            { type: "sword", material: "steel", enchantment: 3, cursed: false },
306	            { type: "sword", material: "steel", enchantment: 2, cursed: false },
307	          ],
308	        },
309	      ],
310	    });
311	
312	    expect(output).toEqual({ results: [{ premium: 225 }] });
313	  });
314	  // STRUCTURAL TURNING POINT: the first test needing TWO steps in one
315	  // scenario, so it forces out the long-standing `steps[0]` assumption.
316	  // The follow-up discount depends on the step's POSITION, not on the
317	  // customer record. Results must be one per step, in step order.
318	  //   step 0 (first contract):  100 + 10 + 5      = 115 G
319	  //   step 1 (second contract): 100 + 10 − 15 + 5 = 100 G
320	  // Note the first-insurance surcharge still applies on the follow-up.
321	  it("should apply 15 % discount on each contract after the first", () => {
322	    const sword = { type: "sword", material: "steel", enchantment: 3, cursed: false };
323	    const output = runScenario({
324	      customer: { yearsWithMHPCO: 0 },
325	      steps: [
326	        { op: "quote", items: [sword] },
327	        { op: "quote", items: [sword] },
328	      ],
329	    });
330	
331	    expect(output).toEqual({ results: [{ premium: 115 }, { premium: 100 }] });
332	  });
333	
334	  // --- Modifier scope on multi-item policies ---
335	  // THE decisive modifier-scope test. Policy base = 100 + 60 = 160; the curse
336	  // adds 50 % of the SWORD's own 100 G = 50 (→ 210 before further modifiers),
337	  // NOT 50 % of the 160 G policy total. Then first insurance is 10 % of the
338	  // POLICY base (160) = 16, plus the 5 G fee → 231 G.
339	  // This DISCRIMINATES: a policy-wide curse reading gives 50 % of 160 = 80,
340	  // i.e. 261 G. Every earlier curse test used one item, where both readings
341	  // coincide — so this is the first test that can tell them apart.
342	  // Enchantments 3 and 2 are below the threshold of 5, isolating the curse.
343	  it("should apply curse surcharge to the cursed item only — cursed sword + plain amulet → 210 G before fee", () => {
344	    const output = runScenario({
345	      customer: { yearsWithMHPCO: 0 },
346	      steps: [
347	        {
348	          op: "quote",
349	          items: [
350	            { type: "sword", material: "steel", enchantment: 3, cursed: true },
351	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
352	          ],
353	        },
354	      ],
355	    });
356	
357	    expect(output).toEqual({ results: [{ premium: 231 }] });
358	  });
359	  // Policy-wide half of the modifier-scope rule: loyalty and first insurance
360	  // are percentages of the SUMMED policy base (160), fee added last.
361	  //   160 base + 16 first insurance − 32 loyalty + 5 fee = 149 G
362	  //
363	  // HONEST LIMITS — this test discriminates neither aspect it describes:
364	  //  · loyalty on the summed base == a per-item reading, since percentages are
365	  //    linear (20 % of 100 + 20 % of 60 = 32 either way);
366	  //  · the fee ordering also coincides — folding the fee into the base gives
367	  //    165 → +16.5 − 33 = 148.5, which ceil()s to the same 149.
368	  // The two integration examples are what genuinely pin the stack and ordering.
369	  it("should apply policy-wide modifiers to the policy base premium and add the fee last", () => {
370	    const output = runScenario({
371	      customer: { yearsWithMHPCO: 3 },
372	      steps: [
373	        {
374	          op: "quote",
375	          items: [
376	            { type: "sword", material: "steel", enchantment: 3, cursed: false },
377	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
378	          ],
379	        },
380	      ],
381	    });
382	
383	    expect(output).toEqual({ results: [{ premium: 149 }] });
384	  });
